w Container instance holding the specified\n25|// CanvasObjects that are manually arranged.\n26|//\n27|// Deprecated: Use container.NewWithoutLayout() instead\n28|func NewContainerWithoutLayout(objects ...CanvasObject) *Container {\n29|\tret := &Container{\n30|\t\tObjects: objects,\n31|\t}\n32|\n33|\tret.size = ret.MinSize()\n34|\treturn ret\n35|}\n36|\n37|// NewContainerWithLayout returns a new Container instance holding the specified\n38|// CanvasObjects which will be laid out according to the specified Layout.\n39|//\n40|// Deprecated: Use container.New() instead\n41|func NewContainerWithLayout(layout Layout, objects ...CanvasObject) *Container {\n42|\tret := &Container{\n43|\t\tObjects: objects,\n44|\t\tLayout:  layout,\n45|\t}\n46|\n47|\tret.size = layout.MinSize(objects)\n48|\tret.layout()\n49|\treturn ret\n50|}\n51|\n52|// Add appends the specified object to the items this container manages.\n53|//\n54|// Since: 1.4\n55|func (c *Container) Add(add CanvasObject) {\n56|\tc.Objects = append(c.Objects, add)\n57|\tc.layout()\n58|}\n59|\n60|// AddObject adds another CanvasObject to the set this Container holds.\n61|//\n62|// Deprecated: Use replacement Add() function\n63|func (c *Container) AddObject(o CanvasObject) {\n64|\tc.Add(o)\n65|}\n66|\n67|// MinSize calculates the minimum size of a Container.\n68|// This is delegated to the Layout, if specified, otherwise it will mimic MaxLayout.\n69|func (c *Container) MinSize() Size {\n70|\tif c.Layout != nil {\n71|\t\treturn c.Layout.MinSize(c.Objects)\n72|\t}\n73|\n74|\tminSize := NewSize(1, 1)\n75|\tfor _, child := range c.Objects {\n76|\t\tminSize = minSize.Max(child.MinSize())\n77|\t}\n78|\n79|\treturn minSize\n80|}\n81|\n82|// Move the container (and all its children) to a new position, relative to its parent.\n83|func (c *Container) Move(pos Position) {\n84|\tc.position = pos\n85|}\n86|\n87|// Position gets the current position of this Container, relative to its parent.\n88|func (c *Container) Position() Position {\n89|\treturn c.position\n90|}\n91|\n92|// Resize sets a new size for the Container.\n93|func (c *Container) Resize(size Size) {\n94|\tif c.size == size {\n95|\t\treturn\n96|\t}\n97|\n98|\tc.size = size\n99|\tc.layout()\n100|}\n101|\n102|// Size returns the current size of this container.\n103|func (c *Container) Size() Size {\n104|\treturn c.size\n105|}\n106|\n107|// Show sets this container, and all its children, to be visible.\n108|func (c *Container) Show() {\n109|\tif !c.Hidden {\n110|\t\treturn\n111|\t}\n112|\n113|\tc.Hidden = false\n114|}\n115|\n116|// Hide sets this container, and all its children, to be not visible.\n117|func (c *Container) Hide() {\n118|\tif c.Hidden {\n119|\t\treturn\n120|\t}\n121|\n122|\tc.Hidden = true\n123|}\n124|\n125|// Refresh causes this object to be redrawn in it's current state\n126|func (c *Container) Refresh() {\n127|\tc.layout()\n128|\n129|\tfor _, child := range c.Objects {\n130|\t\tchild.Refresh()\n131|\t}\n132|\n133|\t// this is basically just canvas.Refresh(c) without the package loop\n134|\to := CurrentApp().Driver().CanvasForObject(c)\n135|\tif o == nil {\n136|\t\treturn\n137|\t}\n138|\to.Refresh(c)\n139|}\n140|\n141|// Remove updates the contents of this container to no longer include the specified object.\n142|// This method is not intended to be used inside a loop, to remove all the elements.\n143|// It is much more efficient to just set .Objects to nil instead.\n144|func (c *Container) Remove(rem CanvasObject) {\n145|\tif len(c.Objects) == 0 {\n146|\t\treturn\n147|\t}\n148|\n149|\tfor i, o := range c.Objects {\n150|\t\tif o != rem {\n151|\t\t\tcontinue\n152|\t\t}\n153|\n154|\t\tremoved := make([]CanvasObject, len(c.Objects)-1)\n155|\t\tcopy(removed, c.Objects[:i])\n156|\t\tcopy(removed[i:], c.Objects[i+1:])\n157|\n158|\t\tc.Objects = removed\n159|\t\tc.layout()\n160|\t\treturn\n161|\t}\n162|}\n163|\n164|// Visible returns true if the container is currently visible, false otherwise.\n165|func (c *Container) Visible() bool {\n166|\treturn !c.Hidden\n167|}\n168|\n169|func (c *Container) layout() {\n170|\tif c.Layout != nil {\n171|\t\tc.Layout.Layout(c.Objects, c.size)\n172|\t\treturn\n173|\t}\n174|}"}, {"tool_use_id": "toolu_Ku1dOmamvauhFSEwlSuXKG", "content": "由于设置了show_linenos，以下返回信息为：(行号|)内容 。\n[FILE] 140 lines\n1|// Package app provides app implementations for working with Fyne graphical interfaces.\n2|// The fastest way to get started is to call app.New() which will normally load a new desktop application.\n3|// If the \"ci\" tag is passed to go (go run -tags ci myapp.go) it will run an in-memory application.\n4|package app // import \"fyne.io/fyne/v2/app\"\n5|\n6|import (\n7|\t\"strconv\"\n8|\t\"sync\"\n9|\t\"time\"\n10|\n11|\t\"fyne.io/fyne/v2\"\n12|\t\"fyne.io/fyne/v2/internal\"\n13|\t\"fyne.io/fyne/v2/internal/app\"\n14|\tintRepo \"fyne.io/fyne/v2/internal/repository\"\n15|\t\"fyne.io/fyne/v2/storage/repository\"\n16|\n17|\t\"golang.org/x/sys/execabs\"\n18|)\n19|\n20|// Declare conformity with App interface\n21|var _ fyne.App = (*fyneApp)(nil)\n22|\n23|type fyneApp struct {\n24|\tdriver   fyne.Driver\n25|\ticon     fyne.Resource\n26|\tuniqueID string\n27|\n28|\tlifecycle fyne.Lifecycle\n29|\tsettings  *settings\n30|\tstorage   *store\n31|\tprefs     fyne.Preferences\n32|\n33|\trunning  bool\n34|\trunMutex sync.Mutex\n35|\texec     func(name string, arg ...string) *execabs.Cmd\n36|}\n37|\n38|func (a *fyneApp) Icon() fyne.Resource {\n39|\treturn a.icon\n40|}\n41|\n42|func (a *fyneApp) SetIcon(icon fyne.Resource) {\n43|\ta.icon = icon\n44|}\n45|\n46|func (a *fyneApp) UniqueID() string {\n47|\tif a.uniqueID != \"\" {\n48|\t\treturn a.uniqueID\n49|\t}\n50|\n51|\tfyne.LogError(\"Preferences API requires a unique ID, use app.NewWithID()\", nil)\n52|\ta.uniqueID = \"missing-id-\" + strconv.FormatInt(time.Now().Unix(), 10) // This is a fake unique - it just has to not be reused...\n53|\treturn a.uniqueID\n54|}\n55|\n56|func (a *fyneApp) NewWindow(title string) fyne.Window {\n57|\treturn a.driver.CreateWindow(title)\n58|}\n59|\n60|func (a *fyneApp) Run() {\n61|\ta.runMutex.Lock()\n62|\n63|\tif a.running {\n64|\t\ta.runMutex.Unlock()\n65|\t\treturn\n66|\t}\n67|\n68|\ta.running = true\n69|\ta.runMutex.Unlock()\n70|\n71|\ta.driver.Run()\n72|}\n73|\n74|func (a *fyneApp) Quit() {\n75|\tfor _, window := range a.driver.AllWindows() {\n76|\t\twindow.Close()\n77|\t}\n78|\n79|\ta.driver.Quit()\n80|\ta.settings.stopWatching()\n81|\ta.running = false\n82|}\n83|\n84|func (a *fyneApp) Driver() fyne.Driver {\n85|\treturn a.driver\n86|}\n87|\n88|// Settings returns the application settings currently configured.\n89|func (a *fyneApp) Settings() fyne.Settings {\n90|\treturn a.settings\n91|}\n92|\n93|func (a *fyneApp) Storage() fyne.Storage {\n94|\treturn a.storage\n95|}\n96|\n97|func (a *fyneApp) Preferences() fyne.Preferences {\n98|\tif a.uniqueID == \"\" {\n99|\t\tfyne.LogError(\"Preferences API requires a unique ID, use app.NewWithID()\", nil)\n100|\t}\n101|\treturn a.prefs\n102|}\n103|\n104|func (a *fyneApp) Lifecycle() fyne.Lifecycle {\n105|\treturn a.lifecycle\n106|}\n107|\n108|// New returns a new application instance with the default driver and no unique ID\n109|func New() fyne.App {\n110|\tinternal.LogHint(\"Applications should be created with a unique ID using app.NewWithID()\")\n111|\treturn NewWithID(\"\")\n112|}\n113|\n114|func newAppWithDriver(d fyne.Driver, id string) fyne.App {\n115|\tnewApp := &fyneApp{uniqueID: id, driver: d, exec: execabs.Command, lifecycle: &app.Lifecycle{}}\n116|\tfyne.SetCurrentApp(newApp)\n117|\tnewApp.settings = loadSettings()\n118|\n119|\tnewApp.prefs = newPreferences(newApp)\n120|\tnewApp.storage = &store{a: newApp}\n121|\tif id != \"\" {\n122|\t\tif pref, ok := newApp.prefs.(interface{ load() }); ok {\n123|\t\t\tpref.load()\n124|\t\t}\n125|\n126|\t\troot, _ := newApp.storage.docRootURI()\n127|\t\tnewApp.storage.Docs = &internal.Docs{RootDocURI: root}\n128|\t} else {\n129|\t\tnewApp.storage.Docs = &internal.Docs{} //