// NewAllStrings creates a validator that ensures the input contains all specified substrings.
// Returns nil if all required substrings are present, otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(required []string) fyne.StringValidator {
	if len(required) == 0 {
		return func(text string) error {
			return nil
		}
	}

	return func(text string) error {
		var missing []string
		for _, req := range required {
			if !strings.Contains(text, req) {
