import (
	"fmt"
)

// stringFormat is a String binding that formats its value using fmt.Sprintf
type stringFormat struct {
	base

	format  string
	sources []DataItem
}

// BindingSprintf creates a new String binding that formats multiple source bindings using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf, and sources are the bindings to be formatted.
// The resulting binding is read-only - calls to Set() will return an error.
// When any source binding changes, the formatted string is automatically recalculated.
//
// Since: 2.5
func BindingSprintf(format string, sources ...DataItem) String {
	s := &stringFormat{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings for changes
	listener := NewDataListener(func() {
		s.trigger()
	})

	for _, source := range sources {
		if source != nil {
			source.AddListener(listener)
		}
	}

	return s
}

func (s *stringFormat) Get() (string, error) {
	values := make([]interface{}, 0, len(s.sources))

	for _, source := range s.sources {
		if source == nil {
			values = append(values, nil)
			continue
		}

		// Type assert to extract the actual value
		switch typed := source.(type) {
		case String:
			if val, err := typed.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, "")
			}
		case Bool:
			if val, err := typed.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, false)
			}
		case Int:
			if val, err := typed.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, 0)
			}
		case Float:
			if val, err := typed.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, 0.0)
			}
		case Untyped:
			if val, err := typed.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, nil)
			}
		default:
			// Unknown type, use nil
			values = append(values, nil)
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFormat) Set(string) error {
	// Formatted bindings are read-only
	return fmt.Errorf("cannot set value on a formatted binding")
}
